using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Divergence;

internal sealed class NormalOverlapOperationalDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Divergence/NormalOverlapOperational.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original whole-complex-L1 arbitrary-curvature equality classification and simultaneous standard-predual attainment.",
        H("Original whole-complex-L1 arbitrary-curvature equality classification and simultaneous standard-predual attainment"), Blocks(
            Node("source_hinges", "Original source hinge profiles", "For any actual algebraic positive normal preparation on the entire complex L1, the negative and positive source hinge integrals equal t sigma(1)-a_R(t) and rho(1)-a_R(t). The actual posteriorFamily and pullContinuous preserve both complex moments and the overlap observation. Real min identities and integrability of the original inputs prove the equality; neither endpoint is discarded.", true),
            Node("standardHingeCosts", "Original whole-L1 single-hinge cost set", "This is the cost set itself, before any infimum: all sigma-finite sources of the fixed universe u, all StandardL1Preparation maps on the entire complex L1, all actual a.e. positive complex L1 inputs with exact output moments, and the actual negative or positive hinge integral. The independently defined coefficient-series class is required for every preparation output. The Boolean branch true selects (tq-p)+ and false selects (p-tq)+.", false),
            Node("operationalHinge", "Original operational single-hinge infimum", "Take the real conditional infimum of standardHingeCosts. The attaining-minimum theorem establishes nonemptiness and a genuine least member for every t>0, so no empty-set infimum convention carries the result.", false),
            Node("operational_hinge_eq", "Attained operational normal-overlap formula", "For every t>0, the actual original single-hinge infimum is t sigma(1)-v(t) for the negative branch and rho(1)-v(t) for the positive branch. It is a least element of the actual original cost set. Every source gives a feasible actual normal overlap via its posterior family, giving the lower bound. The attained maximum v(t), standard_posterior_realization, and the universe-lifted whole-L1 preparation supply a source attaining the bound with coefficient-series outputs. No chosen state or division by a functional mass is used. These overlap formulas are antecedents in Hiai--Mosonyi--Tomamichel, Proposition V.1, formulas (V.124)-(V.125).", true),
            Node("originalHockeyValue", "Literal original maximal-hockey curvature value", "The finite affine term f(1)s+f_right_prime(1)(r-s) plus the nonnegative curvature integral of the actual original operational single-hinge infima. Thresholds at most one use the negative branch and the rest use the positive branch; the entire atom at one belongs to the negative branch. This is formula (V.126) with reference point one, including zero and singular inputs and arbitrary finite masses.", false),
            Node("originalHockeyValue_eq_overlap", "Exact operational curvature identification", "The proved original single-hinge formulas identify originalHockeyValue with the two actual optimal-normal-overlap deficit integrals. Splitting at Iic 1 and Ioi 1 retains the complete curvature measure. This equality has no finite-value premise and is consumed by the classification and simultaneous attainment endpoint.", true),
            Node("original_operational_equality_iff_finite_compatibility", "Exact original operational classification", "For any concrete von Neumann algebra in arbitrary Hilbert-space universe v, arbitrary positive coefficient-series rho and sigma, and any real generator convex on the positive ray, assume only that the literal original sInf of standardAttainableCosts in source universe u is real finite. Equality with the literal original maximal-hockey curvature value is equivalent to finite compatibility of actual optimal normal overlaps on the actual curvature support. FiniteCompatibility uses the computed functional antitone secants, not scalar masses alone. The support can be empty, singular continuous, atomic, uncountable, unbounded or accumulate at zero. This theorem is consumed by arbitrary_support_classification.", true),
            Node("arbitrary_support_classification", "Classification and one actual simultaneous minimizing test", "The complete endpoint states finiteness of the original maximal-hockey value, the exact equivalence, and existence under either equivalent condition of one actual whole-complex-L1 Gamma on a finite regular Borel measure on [0,1]. The total measure is rho(1)+sigma(1); both posterior moments are exact, every output is in the independently defined coefficient-series predual, and every overlap on curvature support attains v(t). Its literal closed-perspective cost is the original maximal infimum. The same Gamma constructs a lifted standard-original reverse test in the independent source universe u, with p=x, q=1-x, all outputs in the series predual, and exact finite cost equal to BOTH original operational quantities. Existing unconditional source equivalence and extended attainment are reused. No optimizer, compatible family, full curvature support, finite dimension, trace, injectivity, separability, faithfulness, normalization, support comparability, spectral optimality or finite alphabet is assumed. No necessity for infinity=infinity is asserted. The separate full-support localized-centralizer classification is outside this theorem; worldwide priority remains unresolved.", true),
            Paragraph(Text("Hiai--Mosonyi--Tomamichel, Hockey stick f-divergences, arXiv:2607.08760v1, PDF pp. 34-36 gives the original reverse-test class and operational hockey formulas; (III.11) and (III.16) give the scalar curvature and closed-perspective framework. PDF p. 62 explicitly leaves the last maximal-hockey/maximal equality case open. Standard compactness, positive functional interpolation, Riesz representation and nonnegative integral additivity are antecedents. The separate full-support localized-centralizer classification is outside this statement."))
        )));

    private static DocumentBlock Node(string name, string title, string prose, bool theorem) =>
        Describe.Lean(DescribeId.Create("normaloverlapoperational-" + name.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))),
            theorem ? DescribeRole.Theorem : DescribeRole.Definition);
}
